-- =============================================================================
-- Smart HAS / SmartCare 5.0 - Fase 6
-- 01_ddl_tabelas.sql - modelo fisico Oracle (Oracle 19c ou superior)
--
-- Os nomes de tabelas e colunas sao os mesmos mapeados pelas entidades JPA do
-- back-end Spring Boot. Assim, com o perfil "oracle" ativo, a API le e grava
-- exatamente estas tabelas, e as procedures PL/SQL enxergam os mesmos dados
-- que o app Flutter e o painel Angular.
--
-- Convencoes:
--   * PK numerica com IDENTITY (GENERATED BY DEFAULT), compativel com o
--     GenerationType.IDENTITY do Hibernate;
--   * booleanos como NUMBER(1) com CHECK (0/1);
--   * instantes como TIMESTAMP WITH TIME ZONE (mapeamento padrao do
--     java.time.Instant no Hibernate 6 para Oracle);
--   * enums persistidos como texto, restritos por CHECK;
--   * constraints nomeadas (pk_, fk_, uk_, ck_) e indices (idx_).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- PACIENTE: prontuario monitorado
-- -----------------------------------------------------------------------------
CREATE TABLE patient (
    id                 NUMBER(19)     GENERATED BY DEFAULT AS IDENTITY,
    name               VARCHAR2(120)  NOT NULL,
    age                NUMBER(3)      NOT NULL,
    wearable_connected NUMBER(1)      DEFAULT 1 NOT NULL,
    created_at         TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at         TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_patient          PRIMARY KEY (id),
    CONSTRAINT ck_patient_age      CHECK (age BETWEEN 0 AND 130),
    CONSTRAINT ck_patient_wearable CHECK (wearable_connected IN (0, 1))
);

COMMENT ON TABLE  patient                    IS 'Prontuario do paciente monitorado pelo Smart HAS';
COMMENT ON COLUMN patient.wearable_connected IS '1 = wearable pareado e enviando leituras';

-- -----------------------------------------------------------------------------
-- CONDICOES CLINICAS do paciente (colecao @ElementCollection no JPA)
-- -----------------------------------------------------------------------------
CREATE TABLE patient_condition (
    patient_id     NUMBER(19)    NOT NULL,
    condition_name VARCHAR2(120) NOT NULL,
    CONSTRAINT pk_patient_condition PRIMARY KEY (patient_id, condition_name),
    CONSTRAINT fk_condition_patient FOREIGN KEY (patient_id)
        REFERENCES patient (id) ON DELETE CASCADE
);

COMMENT ON TABLE patient_condition IS 'Condicoes clinicas cronicas de cada paciente';

-- -----------------------------------------------------------------------------
-- USUARIO de acesso a API (paciente, profissional ou administrador)
-- -----------------------------------------------------------------------------
CREATE TABLE app_user (
    id            NUMBER(19)    GENERATED BY DEFAULT AS IDENTITY,
    email         VARCHAR2(120) NOT NULL,
    password_hash VARCHAR2(255) NOT NULL,
    name          VARCHAR2(120) NOT NULL,
    role          VARCHAR2(20)  DEFAULT 'PATIENT' NOT NULL,
    enabled       NUMBER(1)     DEFAULT 1 NOT NULL,
    patient_id    NUMBER(19),
    created_at    TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_app_user         PRIMARY KEY (id),
    CONSTRAINT uk_app_user_email   UNIQUE (email),
    CONSTRAINT ck_app_user_role    CHECK (role IN ('PATIENT', 'PROFESSIONAL', 'ADMIN')),
    CONSTRAINT ck_app_user_enabled CHECK (enabled IN (0, 1)),
    CONSTRAINT fk_app_user_patient FOREIGN KEY (patient_id)
        REFERENCES patient (id) ON DELETE SET NULL
);

COMMENT ON TABLE  app_user               IS 'Credenciais de acesso a API REST (JWT)';
COMMENT ON COLUMN app_user.password_hash IS 'Hash BCrypt - a senha em texto puro nunca e persistida';

-- -----------------------------------------------------------------------------
-- PROFISSIONAL de saude
-- -----------------------------------------------------------------------------
CREATE TABLE doctor (
    id        NUMBER(19)    GENERATED BY DEFAULT AS IDENTITY,
    name      VARCHAR2(120) NOT NULL,
    specialty VARCHAR2(80)  NOT NULL,
    crm       VARCHAR2(30)  NOT NULL,
    available NUMBER(1)     DEFAULT 1 NOT NULL,
    CONSTRAINT pk_doctor           PRIMARY KEY (id),
    CONSTRAINT uk_doctor_crm       UNIQUE (crm),
    CONSTRAINT ck_doctor_available CHECK (available IN (0, 1))
);

COMMENT ON TABLE doctor IS 'Profissionais habilitados a atender pela plataforma';

-- -----------------------------------------------------------------------------
-- CONSULTA (presencial ou teleconsulta)
-- -----------------------------------------------------------------------------
CREATE TABLE appointment (
    id           NUMBER(19)    GENERATED BY DEFAULT AS IDENTITY,
    patient_id   NUMBER(19)    NOT NULL,
    doctor_id    NUMBER(19)    NOT NULL,
    scheduled_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    telemedicine NUMBER(1)     DEFAULT 1 NOT NULL,
    status       VARCHAR2(20)  DEFAULT 'SCHEDULED' NOT NULL,
    notes        VARCHAR2(300),
    CONSTRAINT pk_appointment          PRIMARY KEY (id),
    CONSTRAINT ck_appointment_tele     CHECK (telemedicine IN (0, 1)),
    CONSTRAINT ck_appointment_status   CHECK (status IN ('SCHEDULED', 'CONFIRMED', 'ACTIVE', 'COMPLETED', 'CANCELLED')),
    CONSTRAINT fk_appointment_patient  FOREIGN KEY (patient_id) REFERENCES patient (id) ON DELETE CASCADE,
    CONSTRAINT fk_appointment_doctor   FOREIGN KEY (doctor_id)  REFERENCES doctor (id)
);

CREATE INDEX idx_appointment_patient_time ON appointment (patient_id, scheduled_at);

COMMENT ON TABLE appointment IS 'Agenda de consultas entre paciente e profissional';

-- -----------------------------------------------------------------------------
-- LEITURA DE SENSOR (wearable / gateway IoT)
-- Os CHECKs repetem os limites fisiologicos validados pela API (Bean
-- Validation): nenhuma origem - API, carga em lote ou gateway gravando direto
-- no banco - consegue persistir uma leitura impossivel.
-- -----------------------------------------------------------------------------
CREATE TABLE vital_reading (
    id            NUMBER(19)  GENERATED BY DEFAULT AS IDENTITY,
    patient_id    NUMBER(19)  NOT NULL,
    heart_rate    NUMBER(3)   NOT NULL,
    spo2          NUMBER(4,1) NOT NULL,
    glucose_level NUMBER(3)   NOT NULL,
    bp_systolic   NUMBER(3)   NOT NULL,
    bp_diastolic  NUMBER(3)   NOT NULL,
    temperature   NUMBER(4,1) NOT NULL,
    measured_at   TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_vital_reading   PRIMARY KEY (id),
    CONSTRAINT fk_vital_patient   FOREIGN KEY (patient_id) REFERENCES patient (id) ON DELETE CASCADE,
    CONSTRAINT ck_vital_hr        CHECK (heart_rate    BETWEEN 20   AND 250),
    CONSTRAINT ck_vital_spo2      CHECK (spo2          BETWEEN 50   AND 100),
    CONSTRAINT ck_vital_glucose   CHECK (glucose_level BETWEEN 20   AND 600),
    CONSTRAINT ck_vital_systolic  CHECK (bp_systolic   BETWEEN 50   AND 260),
    CONSTRAINT ck_vital_diastolic CHECK (bp_diastolic  BETWEEN 30   AND 160),
    CONSTRAINT ck_vital_temp      CHECK (temperature   BETWEEN 30   AND 45)
);

-- Consulta mais frequente do sistema: "ultimas N leituras do paciente".
CREATE INDEX idx_vital_patient_measured ON vital_reading (patient_id, measured_at DESC);

COMMENT ON TABLE  vital_reading             IS 'Leituras de sinais vitais enviadas pelo wearable';
COMMENT ON COLUMN vital_reading.spo2        IS 'Saturacao de oxigenio (%)';
COMMENT ON COLUMN vital_reading.temperature IS 'Temperatura corporal (graus Celsius)';

-- -----------------------------------------------------------------------------
-- ALERTA CLINICO (gerado pelo motor de regras ou registrado pela equipe)
-- -----------------------------------------------------------------------------
CREATE TABLE health_alert (
    id              NUMBER(19)    GENERATED BY DEFAULT AS IDENTITY,
    patient_id      NUMBER(19)    NOT NULL,
    type            VARCHAR2(20)  NOT NULL,
    title           VARCHAR2(160) NOT NULL,
    description     VARCHAR2(500) NOT NULL,
    metric          VARCHAR2(60),
    acknowledged    NUMBER(1)     DEFAULT 0 NOT NULL,
    created_at      TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    acknowledged_at TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT pk_health_alert     PRIMARY KEY (id),
    CONSTRAINT fk_alert_patient    FOREIGN KEY (patient_id) REFERENCES patient (id) ON DELETE CASCADE,
    CONSTRAINT ck_alert_type       CHECK (type IN ('URGENT', 'WARNING', 'INFO', 'OK')),
    CONSTRAINT ck_alert_ack        CHECK (acknowledged IN (0, 1)),
    CONSTRAINT ck_alert_ack_date   CHECK (acknowledged = 0 OR acknowledged_at IS NOT NULL)
);

CREATE INDEX idx_alert_patient_ack ON health_alert (patient_id, acknowledged);

COMMENT ON TABLE  health_alert        IS 'Alertas clinicos do paciente';
COMMENT ON COLUMN health_alert.metric IS 'Metrica que originou o alerta automatico (= vital_reference_range.metric_name)';

-- -----------------------------------------------------------------------------
-- PEDIDO DE MEDICAMENTOS (AI Logistics Extension)
-- -----------------------------------------------------------------------------
CREATE TABLE delivery_order (
    id                NUMBER(19)    GENERATED BY DEFAULT AS IDENTITY,
    patient_id        NUMBER(19)    NOT NULL,
    order_code        VARCHAR2(40)  NOT NULL,
    description       VARCHAR2(300) NOT NULL,
    pharmacy_name     VARCHAR2(160) NOT NULL,
    status            VARCHAR2(20)  DEFAULT 'CONFIRMED' NOT NULL,
    distance_km       NUMBER(6,2)   NOT NULL,
    eta_minutes       NUMBER(5),
    proactive_message VARCHAR2(300),
    created_at        TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at        TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_delivery_order    PRIMARY KEY (id),
    CONSTRAINT uk_delivery_code     UNIQUE (order_code),
    CONSTRAINT fk_delivery_patient  FOREIGN KEY (patient_id) REFERENCES patient (id) ON DELETE CASCADE,
    CONSTRAINT ck_delivery_status   CHECK (status IN ('CONFIRMED', 'PREPARING', 'IN_TRANSIT', 'DELIVERED', 'CANCELLED')),
    CONSTRAINT ck_delivery_distance CHECK (distance_km >= 0),
    CONSTRAINT ck_delivery_eta      CHECK (eta_minutes IS NULL OR eta_minutes >= 0)
);

CREATE INDEX idx_delivery_patient_status ON delivery_order (patient_id, status);

COMMENT ON TABLE delivery_order IS 'Pedidos de medicamentos rastreados pela camada AI Logistics';

-- =============================================================================
-- Tabelas novas da Fase 6 (inteligencia no banco)
-- =============================================================================

-- -----------------------------------------------------------------------------
-- FAIXAS DE REFERENCIA: as regras clinicas viram dado parametrizavel.
-- As functions e procedures leem daqui; ajustar um limite e um UPDATE, sem
-- recompilar nenhuma rotina e sem novo deploy da API.
-- -----------------------------------------------------------------------------
CREATE TABLE vital_reference_range (
    metric_code   VARCHAR2(20) NOT NULL,
    metric_name   VARCHAR2(60) NOT NULL,
    unit          VARCHAR2(10) NOT NULL,
    normal_min    NUMBER(6,1)  NOT NULL,
    normal_max    NUMBER(6,1)  NOT NULL,
    attention_min NUMBER(6,1)  NOT NULL,
    attention_max NUMBER(6,1)  NOT NULL,
    weight        NUMBER(3)    NOT NULL,
    display_order NUMBER(2)    NOT NULL,
    CONSTRAINT pk_vital_reference_range PRIMARY KEY (metric_code),
    CONSTRAINT uk_vital_range_name      UNIQUE (metric_name),
    CONSTRAINT ck_vital_range_code      CHECK (metric_code IN ('HEART_RATE', 'SPO2', 'GLUCOSE',
                                                               'SYSTOLIC', 'DIASTOLIC', 'TEMPERATURE')),
    CONSTRAINT ck_vital_range_normal    CHECK (normal_min <= normal_max),
    CONSTRAINT ck_vital_range_nested    CHECK (attention_min <= normal_min AND normal_max <= attention_max),
    CONSTRAINT ck_vital_range_weight    CHECK (weight BETWEEN 0 AND 100)
);

COMMENT ON TABLE  vital_reference_range        IS 'Faixas clinicas de referencia usadas pelo score e pelos alertas';
COMMENT ON COLUMN vital_reference_range.weight IS 'Pontos descontados do score quando a metrica e critica (atencao = 40%)';

-- -----------------------------------------------------------------------------
-- RELATORIO CONSOLIDADO por paciente e periodo (snapshot gerado pela
-- procedure PRC_CONSOLIDAR_RELATORIO). Uma linha por (paciente, periodo).
-- -----------------------------------------------------------------------------
CREATE TABLE patient_report (
    id                    NUMBER(19)     GENERATED BY DEFAULT AS IDENTITY,
    patient_id            NUMBER(19)     NOT NULL,
    period_days           NUMBER(3)      NOT NULL,
    generated_at          TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    readings_count        NUMBER(6)      DEFAULT 0 NOT NULL,
    avg_heart_rate        NUMBER(5,1),
    avg_spo2              NUMBER(4,1),
    avg_glucose           NUMBER(5,1),
    avg_systolic          NUMBER(5,1),
    avg_diastolic         NUMBER(5,1),
    avg_temperature       NUMBER(4,1),
    latest_score          NUMBER(3),
    average_score         NUMBER(5,1),
    risk_level            VARCHAR2(20)   NOT NULL,
    glucose_time_in_range NUMBER(5,1),
    open_alerts           NUMBER(5)      DEFAULT 0 NOT NULL,
    urgent_alerts         NUMBER(5)      DEFAULT 0 NOT NULL,
    alerts_in_period      NUMBER(5)      DEFAULT 0 NOT NULL,
    deliveries_total      NUMBER(5)      DEFAULT 0 NOT NULL,
    deliveries_delivered  NUMBER(5)      DEFAULT 0 NOT NULL,
    summary_text          VARCHAR2(1000),
    CONSTRAINT pk_patient_report        PRIMARY KEY (id),
    CONSTRAINT uk_report_patient_period UNIQUE (patient_id, period_days),
    CONSTRAINT fk_report_patient        FOREIGN KEY (patient_id) REFERENCES patient (id) ON DELETE CASCADE,
    CONSTRAINT ck_report_period         CHECK (period_days BETWEEN 1 AND 365),
    CONSTRAINT ck_report_scores         CHECK (latest_score IS NULL OR latest_score BETWEEN 0 AND 100)
);

COMMENT ON TABLE  patient_report                       IS 'Relatorio clinico consolidado no banco por PL/SQL';
COMMENT ON COLUMN patient_report.glucose_time_in_range IS 'Percentual de leituras de glicemia dentro da faixa normal (Time in Range)';

-- -----------------------------------------------------------------------------
-- LOG DE EXECUCAO das rotinas PL/SQL (governanca e auditoria).
-- Gravado em transacao autonoma: o registro de um erro sobrevive ao ROLLBACK
-- da operacao que falhou.
-- -----------------------------------------------------------------------------
CREATE TABLE routine_execution_log (
    id            NUMBER(19)     GENERATED BY DEFAULT AS IDENTITY,
    routine_name  VARCHAR2(60)   NOT NULL,
    status        VARCHAR2(10)   NOT NULL,
    rows_affected NUMBER(10)     DEFAULT 0 NOT NULL,
    message       VARCHAR2(4000),
    executed_at   TIMESTAMP(6) WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    executed_by   VARCHAR2(128)  DEFAULT USER NOT NULL,
    CONSTRAINT pk_routine_execution_log PRIMARY KEY (id),
    CONSTRAINT ck_routine_log_status    CHECK (status IN ('SUCCESS', 'ERROR'))
);

CREATE INDEX idx_routine_log_name_date ON routine_execution_log (routine_name, executed_at);

COMMENT ON TABLE routine_execution_log IS 'Trilha de auditoria das procedures do Smart HAS';
